mapper.select:
select	*
from	reservation


	and instr(reservation_name, #{searchName}) > 0


	and instr(reservation_phone, #{searchPhone}) > 0


	and reservation_type = #{searchType}


	and reservation_status = #{searchStatus}

mapper.update:
	update	reservation

        	reservation_status = #{reservationStatus},

            reservation_comment = #{reservationComment}


	where	reservation_no = #{reservationNo}
